"""Author and commit case artifacts through the CLI, never edit state.json."""
import csv
import json
import subprocess
import sys
from pathlib import Path
ROOT=Path(__file__).resolve().parent
WORK=ROOT/'workspace'
CASE=WORK/'projects/case'
CASE.mkdir(parents=True,exist_ok=True)

def save(name,data):
    path=CASE/name
    path.write_text(json.dumps(data,ensure_ascii=False,indent=2),encoding='utf-8')
    return str(path)

def cli(*args, allowed=(0,)):
    p=subprocess.run([sys.executable,'-X','utf8','-m','strategist',*args],cwd=WORK,capture_output=True,text=True,encoding='utf-8')
    with (ROOT/'cli-log.jsonl').open('a',encoding='utf-8') as f:
        f.write(json.dumps({'args':args,'exit_code':p.returncode,'stdout':p.stdout,'stderr':p.stderr},ensure_ascii=False)+'\n')
    print(' '.join(args[:3]),'exit',p.returncode)
    if p.returncode not in allowed:
        print(p.stdout,p.stderr)
        raise RuntimeError('CLI failure; see cli-log.jsonl')
    return p

def evidence(source,number):
    path=ROOT/'materials'/({'cohorts':'cohorts.csv'}.get(source,source+'.md'))
    if source=='cohorts':
        row=list(csv.reader(path.read_text(encoding='utf-8-sig').splitlines()))[number-1]
        quote=json.dumps(row,ensure_ascii=False)
        locator='row:'+str(number)
    else:
        quote=path.read_text(encoding='utf-8').splitlines()[number-1]
        locator='line:'+str(number)
    return {'source':source,'locator':locator,'quote':quote}

