def claim(cid,kind,text,refs,confidence='high',reason=None,**more):
    c={'id':cid,'type':kind,'text':text,'evidence':[evidence(s,n) for s,n in refs],'confidence':confidence,
       'confidence_reason':reason or 'Точная арифметика/прямое содержание синтетического снимка; не реальное подтверждение спроса.',**more}
    cli('claim','add','projects/case',save('claim-'+cid+'.json',c))

